shader_type canvas_item;

uniform float exposed_amount : hint_range(0.0, 1.0) = 0.0;
uniform vec4 exposed_color : source_color = vec4(0.878, 0.271, 0.227, 1.0);

void fragment() {
	COLOR.rgb = mix(COLOR.rgb, exposed_color.rgb, exposed_amount * 0.7);
}

func _process(delta: float) -> void:
	if _main == null:
		return
	if not _main.paused:
		var target: float = 1.0 if is_exposed() else 0.0
		amount = move_toward(amount, target, RATE * delta * _main.time_scale)
	var p: Variant = _main.pieces.get(MainScript.PLAYER_ID)
	if p != null:
		p.set_exposed_amount(amount)

group_uniforms surface;
uniform sampler2D albedo_tex : source_color, filter_linear_mipmap, repeat_enable;
uniform vec4 tint : source_color = vec4(1.0);
uniform float uv_scale : hint_range(0.5, 8.0, 0.05) = 3.65;

group_uniforms relief;
uniform sampler2D roughness_tex : filter_linear_mipmap, repeat_enable;
uniform float roughness_scale : hint_range(0.0, 1.0) = 1.0;
uniform sampler2D normal_tex : hint_normal, filter_linear_mipmap, repeat_enable;
uniform float normal_strength : hint_range(0.0, 2.0) = 1.0;

shader_type spatial;
render_mode unshaded;

uniform sampler2D grey_srgb : source_color, filter_nearest;
uniform sampler2D grey_raw : filter_nearest;
uniform bool use_srgb = true;

void fragment() {
	if (use_srgb) {
		ALBEDO = texture(grey_srgb, UV).rgb;
	} else {
		ALBEDO = texture(grey_raw, UV).rgb;
	}
}

var uniforms: Dictionary = {}
for u: Dictionary in shader.get_shader_uniform_list():
	uniforms[String(u["name"])] = u
rep.check("uniform list is exactly [exposed_amount, exposed_color] (case 8)",
	uniforms.size() == 2 and uniforms.has("exposed_amount") and uniforms.has("exposed_color"), uniforms.keys())
var a: Dictionary = uniforms.get("exposed_amount", {})
rep.check("exposed_amount: type float (3), hint_range (1) 0.0..1.0",
	int(a.get("type", -1)) == TYPE_FLOAT and int(a.get("hint", -1)) == PROPERTY_HINT_RANGE
	and String(a.get("hint_string", "")).begins_with("0.0,1.0"), [a.get("type"), a.get("hint"), a.get("hint_string")])
var c: Dictionary = uniforms.get("exposed_color", {})
rep.check("exposed_color: type vec4 (20)", int(c.get("type", -1)) == TYPE_COLOR, c.get("type"))
